// LAB: Publish a caller-supplied payload
// Build a one-shot publication function. A worker writes a non-atomic payload then releases a ready flag; the caller acquires that flag before reading the payload.
// This starter verifies the original example. Extend it to satisfy the lab checks.
#include <atomic>
#include <cassert>
#include <iostream>
#include <thread>

int main() {
    int payload = 0;
    std::atomic<bool> ready{false};
    int observed = 0;
    std::thread producer([&] {
        payload = 42;
        ready.store(true, std::memory_order_release);
    });
    std::thread consumer([&] {
        while (!ready.load(std::memory_order_acquire)) std::this_thread::yield();
        observed = payload;
    });
    producer.join();
    consumer.join();
    std::cout << observed << '\n';
    assert(observed == 42);
}

#include <atomic>
#include <cassert>
#include <iostream>
#include <thread>
#include <future>

int publish(int value) {
    int payload = 0;
    std::atomic<bool> ready{false};
    auto producer = std::async(std::launch::async,[&] {
        payload = value;
        ready.store(true,std::memory_order_release);
    });
    while(!ready.load(std::memory_order_acquire)) std::this_thread::yield();
    const int observed = payload;
    producer.get();
    return observed;
}

int main() {
    assert(publish(42) == 42 && publish(-7) == -7);
    std::cout << "first=" << publish(42) << " second=" << publish(-7) << '\n';
}
